const msg = $json.message || {};
const text = String(msg.text || msg.caption || '');
const chatId = msg.chat ? msg.chat.id : null;
const m = text.match(/(?:https?|hxxps?):\/\/[^\s<>"')]+/i);
let url = m ? m[0] : '';
url = url.replace(/^hxxp/i, 'http').replace(/\[\.\]/g, '.').replace(/[.,;:!?]+$/, '');
let valid = false; let reason = 'No http(s) URL found in the message.';
if (url) {
  try {
    const pm = url.match(/^(https?):\/\/(?:[^\/?#@]*@)?(\[[^\]]+\]|[^\/?#:]+)/i);
    if (!pm) throw new Error('bad');
    const h = pm[2].toLowerCase();
    const priv = h === 'localhost' || h.endsWith('.local') || h.endsWith('.internal') || h === '0.0.0.0' || h === '[::1]' || /^127\./.test(h) || /^10\./.test(h) || /^192\.168\./.test(h) || /^169\.254\./.test(h) || /^172\.(1[6-9]|2\d|3[01])\./.test(h);
    if (!priv) { valid = true; reason = ''; }
    else { reason = 'Only public http(s) URLs can be traced.'; }
  } catch (e) { reason = 'The URL could not be parsed.'; }
}
const injection = /ignore\s+(all\s+|any\s+)?(the\s+)?(previous|prior|above)\s+(instructions|prompts?)|disregard\s+(the\s+)?(previous|above|prior)|mark\s+(everything|this|it|all)\s+(as\s+)?(safe|benign)|system\s+prompt|you\s+are\s+now|verdict\s*[:=]/i.test(text);
const base = { chat_id: chatId, original_url: url, current_url: url, hop: 0, chain: [], valid: valid, invalid_reason: reason, injection_flag: injection };
return valid ? [1, 2, 3].map(n => ({ json: Object.assign({}, base, { slot: n }) })) : [{ json: base }];

let st;
if ($runIndex === 0) { st = $('Extract URL').first().json; } else { st = $('Record Hop').last().json; }
return [{ json: { chat_id: st.chat_id, original_url: st.original_url, current_url: st.current_url, hop: st.hop, chain: st.chain, injection_flag: st.injection_flag } }];

const prev = $('Prepare Hop').last().json;
const r = $input.first().json || {};
const status = (r.statusCode !== undefined && r.statusCode !== null) ? Number(r.statusCode) : null;
const headers = r.headers || {};
const loc = headers.location || headers.Location || null;
const hostOf = (u) => { const m = String(u).match(/^[a-z][a-z0-9+.-]*:\/\/(?:[^\/?#@]*@)?(\[[^\]]+\]|[^\/?#:]+)/i); return m ? m[1].toLowerCase() : ''; };
const originOf = (u) => { const m = String(u).match(/^(https?:\/\/[^\/?#]+)/i); return m ? m[1] : ''; };
const resolveLoc = (l, base) => {
  l = String(l).trim();
  if (/^https?:\/\//i.test(l)) return l;
  if (l.indexOf('//') === 0) return base.split(':')[0] + ':' + l;
  if (l.charAt(0) === '/') return originOf(base) + l;
  return originOf(base) + '/' + l;
};
const hop = prev.hop + 1;
let next = null;
if (loc && status !== null && status >= 300 && status < 400) { next = resolveLoc(loc, prev.current_url); }
const err = r.error ? String((r.error.message || r.error)).slice(0, 120) : null;
const chain = prev.chain.concat([{ hop: hop, url: prev.current_url, status: status, location: next, error: err }]);
const cont = !!next && hop < 3;
const finalUrl = next || prev.current_url;
const host = hostOf(finalUrl);
const isIp = /^\d{1,3}(\.\d{1,3}){3}$/.test(host) || host.indexOf(':') >= 0;
const labels = host.split('.').filter(Boolean);
let reg = host;
if (labels.length > 2) {
  const sld = labels[labels.length - 2];
  const tld = labels[labels.length - 1];
  const multi = tld.length === 2 && ['co','com','org','net','gov','ac','edu'].indexOf(sld) >= 0;
  reg = labels.slice(multi ? -3 : -2).join('.');
}
return [{ json: Object.assign({}, prev, { current_url: finalUrl, hop: hop, chain: chain, cont: cont, final_url: finalUrl, final_host: host, rdap_domain: isIp ? 'invalid' : reg, is_ip: isIp, truncated: !!next && !cont }) }];

const st = $('Record Hop').last().json;
const rdItems = $input.all().map(i => i.json);
let rd = rdItems.length ? rdItems[0] : {};
if (rd && typeof rd.data === 'string') { try { rd = JSON.parse(rd.data); } catch (e) { rd = {}; } }
let regDate = null;
const events = Array.isArray(rd.events) ? rd.events : [];
for (const e of events) { if (e && e.eventAction === 'registration' && e.eventDate) { regDate = e.eventDate; break; } }
let age = null;
if (regDate) { const t = Date.parse(regDate); if (!isNaN(t)) age = Math.max(0, Math.floor((Date.now() - t) / 86400000)); }
const allUrls = st.chain.map(h => h.url).concat([st.final_url]);
const hosts = allUrls.map(u => { const m = String(u).match(/^[a-z][a-z0-9+.-]*:\/\/(?:[^\/?#@]*@)?(\[[^\]]+\]|[^\/?#:]+)/i); return m ? m[1].toLowerCase() : ''; });
const signals = []; let score = 0;
const add = (n, s) => { score += n; signals.push(s); };
if (age === null) add(1, 'domain age unknown (RDAP lookup failed or no registration event)');
else if (age < 30) add(3, 'domain registered only ' + age + ' days ago');
else if (age < 90) add(1, 'domain registered ' + age + ' days ago (under 90)');
if (st.is_ip) add(2, 'final destination is a raw IP address');
if (hosts.some(h => h.indexOf('xn--') >= 0)) add(2, 'punycode (possible homograph) host in chain');
if (allUrls.some(u => /^https?:\/\/[^/]*@/.test(u))) add(2, 'credentials-style @ in URL authority');
const shorteners = ['bit.ly','tinyurl.com','t.co','goo.gl','ow.ly','is.gd','cutt.ly','rb.gy','shorturl.at','t.ly'];
if (shorteners.indexOf(hosts[0]) >= 0) add(1, 'submitted link uses a URL shortener');
if (new Set(hosts.filter(Boolean)).size > 1) add(1, 'redirect chain crosses domains');
if (st.chain.length >= 3) add(1, 'three or more redirect hops');
if (st.truncated) add(1, 'chain still redirecting after 3 hops');
if (/^https:/i.test(allUrls[0]) && /^http:/i.test(st.final_url)) add(2, 'HTTPS downgraded to HTTP');
if (/(login|signin|verify|secure|account|update|password|wallet|bank|invoice|support)/i.test(st.final_url)) add(1, 'credential-themed keyword in final URL');
if (/\.(zip|top|xyz|click|tk|ml|ga|cf|gq|work|support|country|kim)$/i.test(st.final_host)) add(1, 'high-abuse TLD');
if (st.chain.some(h => h.error)) add(1, 'a hop failed to respond');
if (st.injection_flag) add(2, 'submitted message contains prompt-injection text aimed at the analyser');
const floor = score >= 5 ? 'malicious' : (score >= 2 ? 'suspicious' : 'benign');
const evidence = { submitted_url: st.original_url, hops: st.chain, final_url: st.final_url, final_domain: st.final_host, registrable_domain: st.rdap_domain, registration_date: regDate, domain_age_days: age, truncated_after_max_hops: st.truncated, rule_signals: signals, rule_score: score, rule_floor_verdict: floor };
return [{ json: { evidence: evidence, chat_id: st.chat_id, injection_flag: st.injection_flag } }];

const ev = $('Build Evidence').first().json;
const e = ev.evidence;
const ai = ($json && $json.output && typeof $json.output === 'object') ? $json.output : null;
const rank = { benign: 0, suspicious: 1, malicious: 2 };
const valid = (v) => (typeof v === 'string' && rank[v.toLowerCase()] !== undefined) ? v.toLowerCase() : null;
const aiVerdict = ai ? valid(ai.verdict) : null;
const floor = e.rule_floor_verdict;
let verdict = floor; let source = 'rules only (AI unavailable)';
if (aiVerdict) { verdict = rank[aiVerdict] >= rank[floor] ? aiVerdict : floor; source = rank[aiVerdict] >= rank[floor] ? 'AI agent' : 'rule floor overrode AI'; }
const severity = { benign: 'low', suspicious: 'medium', malicious: 'high' }[verdict];
const defang = (s) => String(s).replace(/^http/i, 'hxxp').replace(/\./g, '[.]');
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const reasons = (ai && Array.isArray(ai.reasons) ? ai.reasons.slice(0, 5).map(String) : []).concat(e.rule_signals.length ? [] : []);
const allReasons = reasons.length ? reasons : e.rule_signals.slice(0, 5);
let summary = (ai && ai.summary) ? String(ai.summary).replace(/https?:\/\/\S+/gi, '[link]').slice(0, 400) : ('Rule-based result: ' + e.rule_signals.slice(0, 2).join('; '));
if (summary.length > 140) { summary = summary.slice(0, 137).replace(/\s+\S*$/, '') + '...'; }
const ist = $now.setZone('Asia/Kolkata');
const istTime = ist.toFormat('yyyy-LL-dd HH:mm:ss') + ' IST';
const alertDate = ist.toFormat('yyyy-LL-dd');
const execId = String($execution.id);
const line = '🔴 NGP-045 | exec #' + execId + ' | ' + istTime + ' | ' + verdict + ' / ' + severity + ' | ' + summary;
const chainLines = [];
chainLines.push('0. ' + defang(e.submitted_url) + ' (submitted)');
e.hops.forEach((h) => { const st = h.status === null ? 'no response' : h.status; chainLines.push(h.hop + '. [' + st + '] ' + defang(h.url) + (h.location ? ' -> ' + defang(h.location) : ' (end)') + (h.error ? ' err: ' + h.error : '')); });
const ageTxt = e.domain_age_days === null ? 'unknown' : (e.domain_age_days + ' days (registered ' + String(e.registration_date).slice(0, 10) + ')');
const text = esc(line) + '\n\nHop chain (max 3 hops):\n' + esc(chainLines.join('\n')) + (e.truncated_after_max_hops ? '\n(still redirecting after 3 hops)' : '') + '\n\nFinal domain: ' + esc(defang(e.final_domain)) + '\nDomain age: ' + esc(ageTxt) + '\nVerdict: ' + verdict.toUpperCase() + ' (' + severity + ', ' + esc(source) + ')' + (ev.injection_flag ? '\nPrompt-injection text detected in input and ignored.' : '') + '\n\nReasons:\n' + esc(allReasons.map(r => '- ' + r).join('\n'));
return [{ json: { chat_id: ev.chat_id, text: text, tag: 'NGP-045', execution_id: execId, alert_time_ist: istTime, alert_date: alertDate, verdict: verdict, severity: severity, final_domain: e.final_domain, domain_age_days: e.domain_age_days, summary: summary, alert_line: line } }];

const rows = $input.all().filter(i => Object.keys(i.json).length > 0 && i.json.severity);
const c = { high: 0, medium: 0, low: 0 };
rows.forEach(r => { const s = String(r.json.severity).toLowerCase(); if (c[s] !== undefined) c[s] += 1; });
const ist = $now.setZone('Asia/Kolkata');
const date = ist.toFormat('yyyy-LL-dd');
const text = '🔴 NGP-045 | daily summary | ' + date + ' | ' + rows.length + ' alert(s) | high: ' + c.high + ' | medium: ' + c.medium + ' | low: ' + c.low;
return [{ json: { text: text, total: rows.length, high: c.high, medium: c.medium, low: c.low } }];
